item.command:
/bin/bash -lc "python - <<'PY'
import json, urllib.request
repos=['scanpy','scanpy-scripts','anndata','python-annData','h5ad','scanpypipeline']
for repo in repos:
    url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=50'
    try:
        with urllib.request.urlopen(url, timeout=20) as r:
            data=json.load(r)
        print('REPO', repo, 'count', len(data.get('tags',[])))
        for t in data.get('tags',[])[:20]: print(' ', t.get('name'))
    except Exception as e:
        print('ERR', repo, repr(e))
PY"

