import csv, json
from pathlib import Path
p=Path('run_trace/galaxy_tool_run_010/summary.json')
data=json.loads(p.read_text())
content=None
for out in data['inline_outputs']:
    if out.get('dataset_id')=='f9cad7b01a4721358a58738ca7da9618' and out.get('content'):
        content=out['content']; break
assert content
rows=list(csv.DictReader(content.splitlines(), delimiter='\\t'))
counts={'srm':0,'mrps21':0,'within':0}
for r in rows:
    s=float(r['SRM']); m=float(r['MRPS21']); d=s-m
    if d>1.0:
        counts['srm']+=1
    elif d < -1.0:
        counts['mrps21']+=1
    elif -1.0 <= d <= 1.0:
        counts['within']+=1
    else:
        raise AssertionError((r,d))
print(len(rows), counts, sum(counts.values()))
print(f\"{counts['srm']};{counts['mrps21']};{counts['within']}\")
PY"

